const query = $input.query.toLowerCase();

const kb = {
  "password reset": "To reset password: 1) Go to login page 2) Click Forgot Password 3) Enter email 4) Check inbox for reset link 5) Create new password",
  "vpn": "VPN Setup: 1) Download Cisco AnyConnect 2) Install application 3) Connect to vpn.company.com 4) Enter your credentials 5) Contact IT if connection fails",
  "email": "Email issues: 1) Check internet connection 2) Verify credentials 3) Clear browser cache 4) Try webmail at mail.company.com 5) Contact IT if problem persists",
  "printer": "Printer troubleshooting: 1) Check power and connections 2) Restart printer 3) Remove and re-add printer in settings 4) Update printer drivers 5) Submit ticket if unresolved",
  "software install": "Software installation: Submit request via IT portal with software name and business justification. Approval required from manager. Installation within 2 business days.",
  "slow computer": "Slow performance: 1) Restart computer 2) Close unused applications 3) Check disk space (need 20% free) 4) Run antivirus scan 5) Contact IT if issue continues",
  "wifi": "WiFi issues: 1) Toggle WiFi off/on 2) Forget and reconnect to network 3) Restart device 4) Check if others have same issue 5) Contact IT for network problems",
  "access request": "Access requests: Submit via IT portal specifying system/folder needed and business reason. Manager approval required. Access granted within 1 business day."
};

for (const [key, value] of Object.entries(kb)) {
  if (query.includes(key)) {
    return value;
  }
}

return "No matching knowledge base article found. Please describe your issue in detail or contact IT support directly.";
